import json, pathlib
HERE = pathlib.Path(__file__).resolve().parent
M = json.load(open(HERE / "model2_ppi.json")); NC = json.load(open(HERE / "model2_ppi_nocharter.json")); ag = json.load(open(HERE / "ages.json"))
T = []; n = [0]
def add(kind, parents=(), **kw):
    n[0] += 1; i = f"m2-{n[0]:03d}"; T.append({"id": i, "kind": kind, "parents": list(parents), **kw}); return i
s1 = add("infer", ["m1-030"] if False else [], value="принцип: строки не выбрасываются, у каждой статус и причина",
         note="Замечание пользователя 20.10: сокращать базу и пересчитывать — худшее решение; нужно разбирать причины выбросов. "
              "Все прежние исключения пересмотрены: распределение формулой → сумма по парку; доживание → поправка в модели; "
              "отсрочка и двигатели вне ТОиР → ждут восстановления по 10-K; чартерные и малые перевозчики — в модели со своим уровнем")
s2 = add("infer", [s1], value=f"возраст: строк без возраста 219 → {M['why'].get('нет возраста в B-43', 0)}",
         note="Причина пропусков — мой разбор B-43, а не данные: United в 2023–2024 писал модель «MAX8»/«MAX9» без «737»; не было шаблонов "
              "для DC-9, Saab 340, EMB-120, Dash 8-100/200/300, «DASH8-Q4». Пропущенный год подачи B-43 (Air Wisconsin 2018–19, Hawaiian и GoJet 2025) "
              f"заполняется из соседнего года в пределах 2 лет со сдвигом возраста ({ag['how'].get('возраст перенесён из соседнего года')} записей, помечены)")
s3 = add("infer", [s1], value="двигатели < 15% — только у парка старше 6 лет",
         note="У молодого парка двигатели почти бесплатны до первого капремонта (5–8 лет) — это норма, а правило выбрасывало ровно молодые строки "
              "и завышало начало кривой. Теперь подозрительна низкая доля только у зрелого парка (UA, AS, SkyWest, Endeavor, PSA, Southwest, чартеры) — ждут 10-K")
s4 = add("infer", [s1], value="метод отсрочки проверяется раньше распределения",
         note="Spirit и Frontier ещё и разносили суммы формулой; у отсрочки занижен сам итог по парку, поэтому их годы ждут 10-K, а не идут суммой")
s5 = add("infer", [s1, s2, s3, s4], value=f"строк типа {M['n_rows']}, сумм по перевозчико-годам {M['n_aggs']} ({M['status'].get('agg')} строк внутри), ждут 10-K {M['status'].get('pending')}, нечем объяснить {M['status'].get('unusable')}",
         note="Модель: ln(ставка) = тип + перевозчик + f(возраст; класс) + e·ln(сектор) + доживание (собственный/арендованный парк). "
              "Наблюдения двух видов: строка типа и ln(суммы перевозчика за год) = ln Σ БЧ·exp(η) по его типам. Нелинейные наименьшие квадраты, "
              f"бутстрэп по перевозчикам {M['boot']} повторов. σ = {M['sigma']:.3f}")
add("conclude", [s5], value="цикл 0–25 лет к зрелому: " + ", ".join(f"{g} {v:.2f} [{M['life_ci'][g][0]:.2f}–{M['life_ci'][g][1]:.2f}]" for g, v in M["life"].items()),
    note=f"Доживание: собственный парк ×{M['runout_owned']:.2f}, арендованный ×{M['runout_leased']:.2f}")
add("gap", [s5], value=f"эластичность по сектору {M['e']:.2f} (было −0,36…−0,46)",
    note=f"Выросла после возврата молодых строк; без чартерных перевозчиков — {NC['e']:.2f}, то есть дело не в них. Возможная причина — новые типы "
         "летают длинные сектора и одновременно молоды; разобрать отдельно, пока не использовать для доли циклов")
with open(HERE / "trace" / "m2.jsonl", "w") as f:
    for t in T: f.write(json.dumps(t, ensure_ascii=False) + "\n")
print(len(T))
